        String mode=in.optString("mode","workbench"),recipeName=in.optString("recipeName","");if(!Set.of("workbench","inspect","recipe").contains(mode))throw new IllegalArgumentException("Unknown task mode");
        if(mode.equals("workbench")&&goal.toLowerCase(Locale.ROOT).matches(".*\\b(look at|inspect|describe|see)\\b.*\\b(screen|workspace|interface|canvas|page)\\b.*")&&!goal.toLowerCase(Locale.ROOT).matches(".*\\b(build|create|make|save|run|reuse|edit|change)\\b.*")){mode="inspect";if(!in.has("focus"))in.put("focus",goal.toLowerCase(Locale.ROOT).contains("canvas")?"canvas":goal.toLowerCase(Locale.ROOT).matches(".*\\b(browser|page)\\b.*")?"browser":"workspace");}
        if(mode.equals("workbench")&&goal.toLowerCase(Locale.ROOT).matches(".*\\b(run|reuse)\\b.*\\b(skill|recipe|routine)\\b.*")&&!goal.toLowerCase(Locale.ROOT).matches(".*\\b(edit|change|modify|adapt)\\b.*"))for(Object raw:store.skills()){String name=((JSONObject)raw).getString("name");if(goal.contains(name)){if(!recipeName.isEmpty()&&!recipeName.equals(name))throw new IllegalArgumentException("Choose one saved recipe");recipeName=name;mode="recipe";}}
        var g=new JSONObject().put("id",UUID.randomUUID().toString()).put("goal",goal).put("model",in.optString("model","")).put("visionModel",in.optString("visionModel","")).put("mode",mode).put("focus",in.optString("focus","canvas")).put("status","queued").put("reason","Queued in Java").put("generation",1).put("resumes",0).put("turn",0).put("failures",0).put("createdAt",Instant.now().toString()).put("history",new JSONArray()).put("recent",new JSONArray()).put("frames",new JSONArray()).put("created",false).put("saved",false).put("needsArtifact",goal.toLowerCase(Locale.ROOT).matches(".*\\b(build|create|make|canvas|app|artifact)\\b.*")).put("needsRecipe",goal.toLowerCase(Locale.ROOT).matches(".*\\b(skill|recipe|routine)\\b.*")).put("counterContract",goal.toLowerCase(Locale.ROOT).contains("counter")&&goal.toLowerCase(Locale.ROOT).contains("reset"));
